import { createHash, randomUUID } from 'crypto';
import * as fs from 'fs';
import * as net from 'net';
import * as os from 'os';
import * as path from 'path';
import { processAlive } from './paths';

/**
 * Ownership of a service home: exactly one engine (background daemon or VS Code-hosted) runs per home. The lease is
 * taken before the engine touches anything in the home and released last, after the engine stopped writing.
 *
 * Linux uses an abstract Unix socket and Windows a named pipe, both released by the OS when the owner exits, crashes
 * included. Other platforms use an exclusive lock file holding the owner's pid, reclaimed only once that process is
 * gone. Another local user squatting the name only keeps the engine from starting; it never yields a second engine.
 */

export type LeaseKind = 'os' | 'file';

export type EngineLease = {
  readonly kind: LeaseKind;
  /** Random per acquisition; written to the info file so clients can tell one engine run from the next. */
  readonly instanceId: string;
  /** The home's real path the lease is named after. */
  readonly home: string;
  /** False once released or lost. */
  held(): boolean;
  /** Throws when the lease is no longer held; called before every write that only the owner may make. */
  assertHeld(): void;
  release(): void;
  /** Called once if the lease is lost while this process still runs (lock file removed or taken over). */
  onLost(listener: () => void): void;
};

export class LeaseLostError extends Error {
  readonly code = 'lease-lost';
  constructor(home: string) { super(`this process no longer owns the account service home ${home}`); }
}

/** Default kind on this platform. */
export function defaultLeaseKind(): LeaseKind {
  return process.platform === 'linux' || process.platform === 'win32' ? 'os' : 'file';
}

/**
 * The home's real path, so two spellings of one directory share one lease. A home that does not exist yet is
 * resolved through its nearest existing ancestor (which may be a symlink) with the missing part appended; any
 * other resolution error throws rather than naming a lease that another spelling would not find.
 */
export function canonicalHome(home: string): string {
  let existing = path.resolve(home);
  const missing: string[] = [];
  for (;;) {
    try { return path.join(fs.realpathSync.native(existing), ...missing.reverse()); }
    catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      const parent = path.dirname(existing);
      if ((code !== 'ENOENT' && code !== 'ENOTDIR') || parent === existing) { throw error; }
      missing.push(path.basename(existing));
      existing = parent;
    }
  }
}

function userKey(): string {
  if (typeof process.getuid === 'function') { return `uid:${process.getuid()}`; }
  // Windows: the account name; a fixed key when it cannot be read keeps every process of this user on one lease.
  try { return `user:${os.userInfo().username.toLowerCase()}`; } catch { return 'user:unknown'; }
}

/** The OS endpoint name of a home's lease; independent of the home's socket path. */
export function leaseEndpoint(home: string): string {
  const key = process.platform === 'win32' ? canonicalHome(home).toLowerCase() : canonicalHome(home);
  const name = 'ai-usage-engine-' + createHash('sha256').update(`${userKey()}\0${key}`).digest('hex').slice(0, 32);
  return process.platform === 'win32' ? `\\\\.\\pipe\\${name}` : `\0${name}`;
}

export const engineLockFile = (home: string): string => path.join(home, 'engine.lock');

/** How often a file lease checks that its lock file still names this owner, besides the check before every write. */
const FILE_LEASE_CHECK_MS = 5_000;

/**
 * Takes the home's lease, or returns undefined when another live process holds it. `kind: 'file'` forces the lock
 * file on any platform (tests); `'os'` is only available on Linux and Windows.
 */
export async function acquireEngineLease(home: string, options: { kind?: LeaseKind } = {}): Promise<EngineLease | undefined> {
  const kind = options.kind ?? defaultLeaseKind();
  const real = canonicalHome(home);
  if (kind === 'os') {
    if (process.platform !== 'linux' && process.platform !== 'win32') { throw new Error('OS-owned leases need Linux or Windows.'); }
    return acquireOsLease(real);
  }
  return acquireFileLease(real);
}

type LeaseState = { held: boolean; listeners: Array<() => void> };

function makeLease(kind: LeaseKind, home: string, instanceId: string, state: LeaseState, release: () => void): EngineLease {
  return {
    kind, instanceId, home,
    held: () => state.held,
    assertHeld: () => { if (!state.held) { throw new LeaseLostError(home); } },
    release: () => { if (!state.held) { return; } state.held = false; state.listeners = []; release(); },
    onLost: (listener) => { state.listeners.push(listener); }
  };
}

function lost(state: LeaseState): void {
  if (!state.held) { return; }
  state.held = false;
  const listeners = state.listeners;
  state.listeners = [];
  for (const listener of listeners) { try { listener(); } catch { /* A listener must not keep the others from running. */ } }
}

function acquireOsLease(home: string): Promise<EngineLease | undefined> {
  const endpoint = leaseEndpoint(home);
  return new Promise((resolve, reject) => {
    // The lease endpoint answers nothing: it exists only to be held. Connections are dropped at once.
    const server = net.createServer((socket) => socket.destroy());
    const onError = (error: NodeJS.ErrnoException) => {
      server.close();
      if (error.code === 'EADDRINUSE' || error.code === 'EACCES') { resolve(undefined); } else { reject(error); }
    };
    server.once('error', onError);
    server.listen(endpoint, () => {
      server.off('error', onError);
      server.unref();
      const state: LeaseState = { held: true, listeners: [] };
      server.on('error', () => lost(state));
      server.on('close', () => lost(state));
      resolve(makeLease('os', home, randomUUID(), state, () => server.close()));
    });
  });
}

type LockRecord = { pid: number; instanceId: string; startedAt?: string };

function readLock(file: string): { text: string; record?: LockRecord } | undefined {
  let text: string;
  try { text = fs.readFileSync(file, 'utf8'); } catch { return undefined; }
  try {
    const parsed = JSON.parse(text) as Partial<LockRecord>;
    if (typeof parsed.pid === 'number' && typeof parsed.instanceId === 'string') { return { text, record: parsed as LockRecord }; }
  } catch { /* Not a lock this service wrote. */ }
  return { text };
}

const TEMPORARY = /^engine\.lock\.(\d+)\.[0-9a-f-]+\.tmp$/;

/**
 * Claims the lock file with a record that is complete before it becomes visible: written to a private temporary file,
 * then hard-linked to the lock name, which fails when the name exists. A crash at any point leaves either no lock or
 * a complete one, never an empty file, and at worst a temporary file that the next acquisition removes.
 */
function claimLock(file: string, record: LockRecord): boolean {
  const temporary = `${file}.${process.pid}.${record.instanceId}.tmp`;
  fs.writeFileSync(temporary, JSON.stringify(record), { mode: 0o600, flag: 'wx' });
  try {
    fs.linkSync(temporary, file);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') { return false; }
    throw error;
  } finally {
    try { fs.unlinkSync(temporary); } catch { /* Already gone. */ }
  }
}

/** Temporary claim files of processes that no longer exist. */
function removeDeadTemporaries(home: string): void {
  let names: string[];
  try { names = fs.readdirSync(home); } catch { return; }
  for (const name of names) {
    const match = TEMPORARY.exec(name);
    if (match && !processAlive(Number(match[1]))) { try { fs.unlinkSync(path.join(home, name)); } catch { /* Raced. */ } }
  }
}

/**
 * Removes the lock only if it is still exactly the dead owner's record seen before: the lock is renamed to a name
 * private to this attempt and checked there. If another process had meanwhile replaced it with a live lock, that lock
 * is put back (a hard link, which fails only if a third process claimed the name in between; then that one owns the
 * home and the displaced owner notices before its next write). No timing assumption: a reclaimer suspended for any
 * time can at worst displace a lock for an instant and restore it.
 */
export function reclaimDeadLock(file: string, seen: string): boolean {
  const aside = `${file}.${process.pid}.${randomUUID()}.reclaim`;
  try { fs.renameSync(file, aside); } catch { return false; }
  let text: string | undefined;
  try { text = fs.readFileSync(aside, 'utf8'); } catch { /* Unreadable: treat as not the one seen. */ }
  if (text === seen) { try { fs.unlinkSync(aside); } catch { /* Gone. */ } return true; }
  try { fs.linkSync(aside, file); } catch { /* A third process owns the home now. */ }
  try { fs.unlinkSync(aside); } catch { /* Gone. */ }
  return false;
}

async function acquireFileLease(home: string): Promise<EngineLease | undefined> {
  fs.mkdirSync(home, { recursive: true, mode: 0o700 });
  const file = engineLockFile(home);
  removeDeadTemporaries(home);
  const record: LockRecord = { pid: process.pid, instanceId: randomUUID(), startedAt: new Date().toISOString() };
  if (!claimLock(file, record)) {
    const existing = readLock(file);
    // A lock this service cannot read was not written by it (claims are complete when visible): never reclaim it.
    if (!existing?.record || existing.record.pid === process.pid || processAlive(existing.record.pid)) { return undefined; }
    if (!reclaimDeadLock(file, existing.text) || !claimLock(file, record)) { return undefined; }
  }
