  const owned = () => readLock(file)?.record?.instanceId === record.instanceId;
  const check = () => { if (state.held && !owned()) { clearInterval(timer); lost(state); } return state.held; };
  const timer = setInterval(check, FILE_LEASE_CHECK_MS);
  timer.unref?.();
  const lease = makeLease('file', home, record.instanceId, state, () => {
    clearInterval(timer);
    try { if (owned()) { fs.unlinkSync(file); } } catch { /* Already removed. */ }
  });
  // A file lease can be lost without an event (the lock removed or displaced): every check reads the file itself.
  return { ...lease, held: check, assertHeld: () => { if (!check()) { throw new LeaseLostError(home); } } };
}

/**
 * Whether some process holds the home's lease, without taking it (taking it, even briefly, could make a host that is
 * starting right now fail). The OS endpoint accepts connections only while held; a lock file counts while its pid lives.
