// These fixtures use synthetic credentials and may contact loopback test servers only.
// A missing injection must fail before it can send a provider or model request.
const allowed = new Set(['127.0.0.1', 'localhost', '::1', '[::1]']);
const check = target => {
  let hostname = typeof target === 'string' || target instanceof URL ? new URL(target).hostname
    : target?.hostname || target?.host || 'localhost';
  if (!allowed.has(hostname) && hostname.includes(':')) { try { hostname = new URL(`http://${hostname}`).hostname; } catch { /* Invalid host is refused below. */ } }
  if (!allowed.has(hostname)) throw new Error(`Parity fixture refused external network host ${hostname}`);
};
for (const name of ['node:http', 'node:https']) {
  const transport = require(name);
  for (const method of ['request', 'get']) {
    const original = transport[method];
    transport[method] = function (target, ...args) { check(target); return original.call(this, target, ...args); };
  }
}
const originalFetch = globalThis.fetch;
globalThis.fetch = (target, options) => { check(target instanceof Request ? target.url : target); return originalFetch(target, options); };
  const file = path.join(sandbox, 'plain-file');
  fs.writeFileSync(file, '');
  fs.chmodSync(sandbox, 0o700);
  // A path through a regular file resolves to that file's would-be child; a permission error is thrown.
  assert.equal(canonicalHome(path.join(file, 'x')), path.join(fs.realpathSync(file), 'x'));
  if (process.platform !== 'win32' && process.getuid?.() !== 0) {
    const closed = fs.mkdtempSync(path.join(sandbox, 'closed-'));
    fs.mkdirSync(path.join(closed, 'inner'));
    fs.chmodSync(closed, 0o000);
    try { assert.throws(() => canonicalHome(path.join(closed, 'inner', 'home')), /EACCES/); }
    finally { fs.chmodSync(closed, 0o700); }
  }
});

test('file lease: a crashed claim leaves no lock and its temporary file is cleaned up', async (t) => {
  const home = newHome(t, undefined);
  // What a process killed between writing its record and linking it leaves behind.
  const leftover = `${engineLockFile(home)}.${2 ** 22 + 4321}.00000000-0000-0000-0000-000000000000.tmp`;
  fs.writeFileSync(leftover, JSON.stringify({ pid: 2 ** 22 + 4321, instanceId: 'crashed' }));
  const lease = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(lease);
  assert.equal(fs.existsSync(leftover), false);
  assert.deepEqual(fs.readdirSync(home).filter((name) => name.startsWith('engine.lock')), ['engine.lock']);
  lease.release();
});

test('file lease: a reclaimer that saw a dead lock but resumes after a new owner claimed it restores that lock', async (t) => {
  const home = newHome(t, undefined);
  const file = engineLockFile(home);
  const dead = JSON.stringify({ pid: 2 ** 22 + 999, instanceId: 'dead' });
  fs.writeFileSync(file, dead);
  // A new owner reclaims and claims while a second reclaimer is suspended with its old reading.
  const owner = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(owner);
  const live = fs.readFileSync(file, 'utf8');
  assert.equal(reclaimDeadLock(file, dead), false, 'the suspended reclaimer does not take a live lock');
  assert.equal(fs.readFileSync(file, 'utf8'), live, 'the live lock is back in place');
  assert.equal(owner.held(), true);
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined);
  owner.release();
});

test('a lock file that is unreadable or names a live process is never reclaimed', async (t) => {
  const home = newHome(t, undefined);
  fs.writeFileSync(engineLockFile(home), '');
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined);
  fs.writeFileSync(engineLockFile(home), JSON.stringify({ pid: process.ppid, instanceId: 'other' }));
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined);
  // Only a provably dead owner is replaced.
  fs.writeFileSync(engineLockFile(home), JSON.stringify({ pid: 2 ** 22 + 12345, instanceId: 'dead' }));
  const lease = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(lease);
  assert.equal(JSON.parse(fs.readFileSync(engineLockFile(home), 'utf8')).instanceId, lease.instanceId);
  lease.release();
  assert.equal(fs.existsSync(engineLockFile(home)), false);
});

test('concurrent hosts of one home: exactly one engine, the others are told to connect to it', async (t) => {
  const home = newHome(t);
  const results = await Promise.allSettled([1, 2, 3, 4].map(() => startServiceHost({ home, mode: 'embedded', version: '9.0.0', engineOptions: offline })));
  const hosts = results.filter((result) => result.status === 'fulfilled').map((result) => result.value);
    assert.equal(await leaseHeld(home), false, 'the lease is released last');
  });
}

test('a file-lease host that loses its lock stops instead of writing beside a new owner', async (t) => {
  const home = newHome(t);
  const host = await startServiceHost({ home, leaseKind: 'file', engineOptions: offline });
  t.after(() => host.stop());
  const client = await connectService({ home, client: 'test' });
  t.after(() => client.close());
  fs.unlinkSync(engineLockFile(home));
  await assert.rejects(client.setConfig({ 'claude.keepAlive.enabled': true }), /no longer owns/);
  assert.equal((await host.stopped).by, 'lease-lost');
  assert.equal(JSON.parse(fs.readFileSync(path.join(home, 'config.json'), 'utf8')).claude.keepAlive?.enabled, undefined);
});

test('the engine runs its background work only with the lease', (t) => {
  const home = newHome(t);
  const engine = new AccountService({ home, version: 'test', log() {}, ...offline });

