s=s[:start]+r'''// --- file lease ---------------------------------------------------------------------------------------------------
//
// Ownership is a numbered claim: `engine.lease/g<n>.json`, holding the claimant's pid, process start identity and a
// random instance id. Its rules, each enforced below:
//
//   R1 A claim is published complete: written to a private temporary file, then hard-linked to its name, which fails
//      when the name exists. A claim file is never modified, renamed or truncated.
//   R2 A claim is deleted only by its own claimant, and only after that claimant saw a higher claim (withdrawal).
//      No process ever deletes or moves another process's claim; a stopping owner adds `g<n>.released` instead.
//   R3 A contender lists the claims, takes the highest, n, and links g<n+1> only if the claimant of g<n> provably
//      exited (no such pid, or a pid now belonging to a process with another start identity) or released it.
//      Nothing is ever taken over because of its age.
//   R4 After linking g<k>, the contender owns the home only if a fresh listing shows no claim above k; otherwise it
//      withdraws (R2) and starts over.
//
// Proof that no second owner arises while an owner lives (any number of contenders, any pauses, any crashes):
//   (a) The highest claim ever published, H, is never deleted: by R2 only a claimant that saw a higher claim deletes
//       its own, and no claim is higher than H. So H stays listed until a higher claim is published.
//   (b) A claim above H can only be g<H+1> (R3 claims "highest seen + 1"; any higher number needs g<H+1> first), and
//       linking it requires H's claimant to have exited or released (R3); a stale listing that missed H only leads to
//       EEXIST or to a lower claim.
//   (c) Owner P of g<p> listed no claim above p after linking (R4). Any claim above p existing at that moment would
//       have been in the listing through (a) (the highest one is present during the whole listing), so H = p then.
//       While P lives and has not released, (b) forbids g<p+1>, so no claim above p ever appears and every other
//       contender's R4 check fails: it withdraws its own lower claim or gets EEXIST, never touching g<p>.
//   (d) Crash recovery: a crash before the link leaves only a temporary file; after the link, a complete claim whose
//       pid is gone, so the next contender links the following number (R3). Nothing waits for time to pass.
// A claim file this service cannot read (it never writes partial ones) fails closed: it is treated as a live owner.
// Claims are small and are not collected while any contender may still rely on them; each start adds one file.

type LockRecord = { pid: number; instanceId: string; startedAt?: string; processStart?: string };

const CLAIM = /^g(\d{16})\.json$/;
const RELEASED = /^g(\d{16})\.released$/;
const TEMPORARY = /^\.claim-(\d+)-[0-9a-f-]+\.tmp$/;
const claimName = (generation: number): string => `g${String(generation).padStart(16, '0')}.json`;
const releasedName = (generation: number): string => `g${String(generation).padStart(16, '0')}.released`;

/**
 * Identity of a running process that changes when its pid is reused: the kernel start time on Linux, `ps`'s start
 * time elsewhere. Undefined when it cannot be read; liveness then rests on the pid alone (which fails closed).
 */
export function processStartIdentity(pid: number): string | undefined {
  try {
    if (process.platform === 'linux') {
      const stat = fs.readFileSync(`/proc/${pid}/stat`, 'utf8');
      return stat.slice(stat.lastIndexOf(')') + 2).split(' ')[19];
    }
    if (process.platform === 'win32') { return undefined; }
    const started = execFileSync('ps', ['-o', 'lstart=', '-p', String(pid)], { encoding: 'utf8', timeout: 2_000, stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    return started || undefined;
  } catch { return undefined; }
}

let ownStart: string | undefined | null = null;
function ownProcessStart(): string | undefined {
  if (ownStart === null) { ownStart = processStartIdentity(process.pid); }
  return ownStart;
}

/** True only when the claimant is provably gone: no process with its pid, or one with another start identity. */
function claimantExited(record: LockRecord): boolean {
  if (record.pid === process.pid) { return record.processStart !== undefined && ownProcessStart() !== undefined && record.processStart !== ownProcessStart(); }
  if (!processAlive(record.pid)) { return true; }
  if (!record.processStart) { return false; }
  const current = processStartIdentity(record.pid);
  return current !== undefined && current !== record.processStart;
}

function readRecord(file: string): LockRecord | undefined {
  try {
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<LockRecord>;
    if (typeof parsed.pid === 'number' && Number.isInteger(parsed.pid) && parsed.pid > 0 && typeof parsed.instanceId === 'string') { return parsed as LockRecord; }
  } catch { /* Unreadable or not written by this service. */ }
  return undefined;
}

export type FileLeaseObservation = {
  /** Highest claim number listed; 0 when there is none. */
  highest: number;
  /** Its claimant, when readable. */
  record?: LockRecord;
  /** free: nothing claimed, or the highest claimant exited or released; held: a live (or unreadable) claim. */
  state: 'free' | 'held';
  released: boolean;
};

function listClaims(directory: string): { claims: number[]; released: Set<number>; temporaries: Array<{ name: string; pid: number }> } {
  const claims: number[] = [];
  const released = new Set<number>();
  const temporaries: Array<{ name: string; pid: number }> = [];
  let names: string[];
  try { names = fs.readdirSync(directory); }
  catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') { return { claims, released, temporaries }; } throw error; }
  for (const name of names) {
    let match = CLAIM.exec(name);
    if (match) { claims.push(Number(match[1])); continue; }
    match = RELEASED.exec(name);
    if (match) { released.add(Number(match[1])); continue; }
    match = TEMPORARY.exec(name);
    if (match) { temporaries.push({ name, pid: Number(match[1]) }); }
  }
  return { claims, released, temporaries };
}

/** R3's reading of the directory. Exported for the ownership regression tests, which interleave contenders with it. */
export function observeFileLease(home: string): FileLeaseObservation {
  const directory = fileLeaseDirectory(home);
  const { claims, released } = listClaims(directory);
  const highest = claims.length ? Math.max(...claims) : 0;
  if (!highest) { return { highest, state: 'free', released: false }; }
  const record = readRecord(path.join(directory, claimName(highest)));
  const isReleased = released.has(highest);
  // A claim that vanished between listing and reading was withdrawn by its claimant (R2): look again.
  if (!record && !fs.existsSync(path.join(directory, claimName(highest)))) { return observeFileLease(home); }
  const free = isReleased || (record !== undefined && claimantExited(record));
  return { highest, record, state: free ? 'free' : 'held', released: isReleased };
}

/** R1: publishes claim `generation` complete, or returns false when that number is taken. */
export function publishFileClaim(home: string, generation: number, record: LockRecord): boolean {
  const directory = fileLeaseDirectory(home);
  fs.mkdirSync(directory, { recursive: true, mode: 0o700 });
  const temporary = path.join(directory, `.claim-${process.pid}-${record.instanceId}.tmp`);
  fs.writeFileSync(temporary, JSON.stringify(record), { mode: 0o600, flag: 'wx' });
  try {
    fs.linkSync(temporary, path.join(directory, claimName(generation)));
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') { return false; }
    throw error;
  } finally {
    try { fs.unlinkSync(temporary); } catch { /* Already gone. */ }
  }
}

/** R4: whether claim `generation` is the highest listed. */
export function fileClaimIsHighest(home: string, generation: number): boolean {
  const { claims } = listClaims(fileLeaseDirectory(home));
  return claims.length > 0 && Math.max(...claims) === generation;
}

/** R2: removes this process's own claim, which a higher claim superseded before it became the owner. */
export function withdrawFileClaim(home: string, generation: number, instanceId: string): void {
  const file = path.join(fileLeaseDirectory(home), claimName(generation));
  if (readRecord(file)?.instanceId === instanceId) { try { fs.unlinkSync(file); } catch { /* Already gone. */ } }
}

/** Temporary claim files of exited processes; never a claim. */
function removeDeadTemporaries(home: string): void {
  const directory = fileLeaseDirectory(home);
  for (const { name, pid } of listClaims(directory).temporaries) {
    if (pid !== process.pid && !processAlive(pid)) { try { fs.unlinkSync(path.join(directory, name)); } catch { /* Raced. */ } }
  }
}

export function newFileLeaseRecord(): LockRecord {
  return { pid: process.pid, instanceId: randomUUID(), startedAt: new Date().toISOString(), processStart: ownProcessStart() };
}

async function acquireFileLease(home: string): Promise<EngineLease | undefined> {
  fs.mkdirSync(fileLeaseDirectory(home), { recursive: true, mode: 0o700 });
  removeDeadTemporaries(home);
  const record = newFileLeaseRecord();
  let generation = 0;
  for (let attempt = 0; attempt < FILE_LEASE_ATTEMPTS && !generation; attempt++) {
    const seen = observeFileLease(home);
    if (seen.state === 'held') { return undefined; }
    const next = seen.highest + 1;
    if (!publishFileClaim(home, next, record)) { continue; }
    if (fileClaimIsHighest(home, next)) { generation = next; break; }
    withdrawFileClaim(home, next, record.instanceId);
  }
  if (!generation) { return undefined; }
  const directory = fileLeaseDirectory(home);
  const file = path.join(directory, claimName(generation));
  const state: LeaseState = { held: true, listeners: [] };
  // Only an outside hand (someone deleting the files) can make this false while the owner lives; it then stops.
  const owned = () => readRecord(file)?.instanceId === record.instanceId && !fs.existsSync(path.join(directory, releasedName(generation)));
  const check = () => { if (state.held && !owned()) { clearInterval(timer); lost(state); } return state.held; };
  const timer = setInterval(() => { if (state.held && !fileClaimIsHighest(home, generation)) { clearInterval(timer); lost(state); } else { check(); } }, FILE_LEASE_CHECK_MS);
  timer.unref?.();
  const lease = makeLease('file', home, record.instanceId, state, () => {
    clearInterval(timer);
    // The claim stays (R2): the marker tells the next contender it may claim the following number.
    try { fs.writeFileSync(path.join(directory, releasedName(generation)), '', { mode: 0o600, flag: 'wx' }); } catch { /* Already released. */ }
  });
  return { ...lease, held: check, assertHeld: () => { if (!check()) { throw new LeaseLostError(home); } } };
}

