  const b = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(b);
  const incumbent = claimFile(home, 2);
  const before = fingerprint(incumbent);
  // Third contender C arrives while B lives.
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined, 'C is refused while B lives');
  assert.equal(b.held(), true);
  // A resumes with its stale reading: its claim of the next number collides, and its fresh look sees B alive.
  assert.equal(publishFileClaim(home, seenByA.highest + 1, a), false);
  assert.equal(fingerprint(incumbent), before, 'the incumbent claim was not touched');
  assert.equal(b.held(), true);
  assert.equal(observeFileLease(home).state, 'held');
  // A and C retry the whole acquisition, concurrently: both refused, and nothing was removed at any point.
  assert.deepEqual(await Promise.all([acquireEngineLease(home, { kind: 'file' }), acquireEngineLease(home, { kind: 'file' })]), [undefined, undefined]);
  assert.equal(fingerprint(incumbent), before);
  assert.deepEqual(claims(home), [path.basename(claimFile(home, 1)), path.basename(incumbent)]);
  assert.equal(b.held(), true);
  b.release();
  // Released, the next contender takes the following number; the earlier claims stay as they were.
  const c = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(c);
  assert.equal(fingerprint(incumbent), before);
  assert.equal(claims(home).length, 3);
  c.release();
});

test('file lease: a stale claim that lands below the owner is withdrawn by its claimant and never becomes owner', async (t) => {
  const home = newHome(t, undefined);
  deadClaim(home, 1);
  const a = newFileLeaseRecord();
  const seenByA = observeFileLease(home);
  // Meanwhile: E claimed 2 and crashed, B took 3; claim 2 is then gone (withdrawn by its own claimant, the only way).
  deadClaim(home, 2);
  const b = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(b);
  const before = fingerprint(claimFile(home, 3));
  fs.unlinkSync(claimFile(home, 2));
  // A's stale claim of 2 is published, but the check after publication sees 3 above it: A withdraws.
  assert.equal(publishFileClaim(home, seenByA.highest + 1, a), true);
  assert.equal(fileClaimIsHighest(home, 2), false);
  withdrawFileClaim(home, 2, a.instanceId);
  assert.equal(fs.existsSync(claimFile(home, 2)), false);
  assert.equal(fingerprint(claimFile(home, 3)), before);
  assert.equal(b.held(), true);
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined);
  b.release();
});

test('file lease: the live incumbent host keeps its admitted work while stale and new contenders are refused', async (t) => {
  const home = newHome(t);
  deadClaim(home, 1);
  const stale = newFileLeaseRecord();
  const seen = observeFileLease(home);
  const host = await startServiceHost({ home, leaseKind: 'file', engineOptions: { ...offline,
    identityOf: async (provider, credential) => ({ email: `${credential.claudeAiOauth.accessToken}@example.com`, accountId: `account-${credential.claudeAiOauth.accessToken}` }) } });
  t.after(() => host.stop().catch(() => undefined));
  const before = fingerprint(claimFile(home, 2));
  // Admitted work of the incumbent, queued behind a sweep.
  let release;
  host.service.automation.pending = new Promise((resolve) => { release = resolve; });
  const admitted = host.service.handle('profiles.importCredential', { provider: 'claude', name: 'Kept', credential: { claudeAiOauth: { accessToken: 'k', refreshToken: 'r', expiresAt: 9999999999999 } } }, 1, {});
  assert.equal(publishFileClaim(home, seen.highest + 1, stale), false);
  await assert.rejects(startServiceHost({ home, leaseKind: 'file', ownerWaitMs: 200, engineOptions: offline }),
    (error) => error instanceof EngineOwnedError && error.code === 'owner-running');
  release();
  assert.equal((await admitted).status, 'saved');
  assert.equal(fingerprint(claimFile(home, 2)), before);
  assert.equal(readServiceInfo(home).instanceId, host.instanceId);
  assert.equal(host.service.configAuthority.revision >= 0, true);
});

test('file lease: real processes racing for one home yield exactly one owner', async (t) => {
  const home = newHome(t, undefined);
  deadClaim(home, 1);
  const code = `require(${out('runtimeLease.js')}).acquireEngineLease(${JSON.stringify(home)}, { kind: 'file' })
    .then((lease) => { console.log(lease ? 'owner' : 'busy'); setTimeout(() => process.exit(0), 300); });`;
  const outputs = await Promise.all([1, 2, 3, 4, 5, 6].map(() => new Promise((resolve) => {
    const proc = spawn(process.execPath, ['-e', code], { env: process.env, stdio: ['ignore', 'pipe', 'inherit'] });
    let text = '';
    proc.stdout.on('data', (chunk) => { text += chunk; });
    proc.once('exit', () => resolve(text.trim()));
  })));
  assert.equal(outputs.filter((line) => line === 'owner').length, 1, outputs.join(','));
  assert.equal(outputs.filter((line) => line === 'busy').length, 5);
});

test('file lease: a crash before publication leaves only a temporary file, which the next acquisition removes', async (t) => {
  const home = newHome(t, undefined);
