  const lease = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(lease);
  assert.equal(fs.existsSync(leftover), false);
  assert.deepEqual(claims(home), [path.basename(claimFile(home, 1))]);
  lease.release();
});

test('file lease: a crash after publication is recovered by the next number, without removing the dead claim', async (t) => {
  const home = newHome(t, undefined);
