test('file lease: a live pid is an owner; a reused pid (another start identity) is not', async (t) => {
  const home = newHome(t, undefined);
  fs.mkdirSync(fileLeaseDirectory(home), { recursive: true });
  const parentStart = processStartIdentity(process.ppid);
  fs.writeFileSync(claimFile(home, 1), JSON.stringify({ pid: process.ppid, instanceId: 'parent', processStart: parentStart }));
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined, 'the same live process keeps it');
  fs.writeFileSync(claimFile(home, 1), JSON.stringify({ pid: process.ppid, instanceId: 'parent' }));
  assert.equal(await acquireEngineLease(home, { kind: 'file' }), undefined, 'without a start identity a live pid fails closed');
  if (parentStart === undefined) { return; }
  fs.writeFileSync(claimFile(home, 1), JSON.stringify({ pid: process.ppid, instanceId: 'reused', processStart: `${parentStart}-before-reuse` }));
  const lease = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(lease, 'a pid now naming another process is not the claimant');
  lease.release();
});

test('file lease: a release is a marker; this process and others take the next number', async (t) => {
  const home = newHome(t, undefined);
  const first = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(first);
  first.release();
  assert.equal(await leaseHeld(home, { kind: 'file' }), false);
  assert.ok(fs.existsSync(claimFile(home, 1)), 'the released claim stays');
  const second = await acquireEngineLease(home, { kind: 'file' });
  assert.ok(second);
  assert.equal(fs.existsSync(claimFile(home, 2)), true);
  assert.equal(first.held(), false);
  second.release();
});

